// Plain data structs for the compiled-in content (PLAN §7.4). The tables are
// generated by cxxman-gen into data.cpp; nothing here allocates.
#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <span>
#include <string_view>

namespace cxxman {

// Each enum has one list of spellings, used by the generator to parse data/ and
// by the renderer to print. Add a new standard here (PLAN §6.5), nowhere else.

enum class Kind : std::uint8_t {
  Function, Algorithm, Class, Member, Alias, Trait,
  Concept, Constant, Macro, Object, Enum,
  Unknown,  // index names whose kind is not known yet; never valid on a card
};
inline constexpr std::array<std::string_view, 11> kind_names{
    "function", "algorithm", "class",    "member", "alias", "trait",
    "concept",  "constant",  "macro",    "object", "enum"};

enum class Std : std::uint8_t {
  Cpp98, Cpp11, Cpp14, Cpp17, Cpp20, Cpp23, Cpp26, Cpp29,
  Unknown,  // not given
};
inline constexpr std::array<std::string_view, 8> std_names{
    "C++98", "C++11", "C++14", "C++17", "C++20", "C++23", "C++26", "C++29"};
// The newest standard data may name; later values are reserved.
inline constexpr Std latest_std = Std::Cpp26;

enum class Level : std::uint8_t { Ub, Warn, Perf };
inline constexpr std::array<std::string_view, 3> level_names{"ub", "warn", "perf"};

template <class E, std::size_t N>
constexpr std::optional<E> enum_from(const std::array<std::string_view, N>& names,
                                     std::string_view s) noexcept {
  for (std::size_t i = 0; i < N; ++i)
    if (names[i] == s) return static_cast<E>(i);
  return std::nullopt;
}

constexpr std::string_view to_string(Kind k) noexcept {
  auto i = static_cast<std::size_t>(k);
  return i < kind_names.size() ? kind_names[i] : std::string_view{};
}
constexpr std::string_view to_string(Std s) noexcept {
  auto i = static_cast<std::size_t>(s);
  return i < std_names.size() ? std_names[i] : std::string_view{};
}
constexpr std::string_view to_string(Level l) noexcept {
  return level_names[static_cast<std::size_t>(l)];
}

// Base URL; Entry::url and IndexName::url are paths below it.
inline constexpr std::string_view cppreference_base = "https://en.cppreference.com/cpp/";

struct Signature {
  std::string_view text{}, note{};
  Std since = Std::Unknown;
};

// A card example (title empty) or a recipe variant (comment empty).
struct Snippet {
  std::string_view title{}, code{}, comment{};
  Std std = Std::Unknown;
};

struct Gotcha {
  Level level = Level::Warn;
  std::string_view text{};
};

struct Group {
  std::string_view title{};
  std::span<const std::string_view> names{};
  Std since = Std::Unknown;
};

struct Support {
  std::string_view gcc{}, clang{}, msvc{}, apple_clang{}, ftm{}, ftm_value{};
};

struct Entry {
  std::string_view id{}, name{}, header{}, summary{}, complexity{}, url{}, parent{}, verified{};
  Kind kind = Kind::Unknown;
  Std since = Std::Unknown;
  Support support{};
  std::span<const std::string_view> badges{}, aliases{}, tags{}, see_also{};
  std::span<const Signature> signatures{};
  std::span<const Group> members{};
  std::span<const Snippet> examples{};
  std::span<const Gotcha> gotchas{};
};

struct Recipe {
  std::string_view id{}, title{}, summary{};
  std::span<const std::string_view> tags{}, uses{};
  std::span<const Snippet> variants{};
  std::span<const Gotcha> gotchas{};
};

struct Row {
  std::string_view label{};
  std::span<const std::string_view> values{};
};

struct Compare {
  std::string_view id{}, title{};
  std::span<const std::string_view> subjects{}, tags{}, verdicts{};
  std::span<const Row> rows{};
};

struct IndexName {
  std::string_view name{}, header{}, url{};
  Kind kind = Kind::Unknown;
  Std since = Std::Unknown;
  std::int32_t entry = -1;  // the card that covers this name, or -1
};

struct Header {
  std::string_view header{}, summary{};
  std::span<const Group> groups{};
};

// One lookup key (an id, alias or name with a leading std:: removed) and what
// it points to. The table is sorted by (folded, key, target, index), so both
// exact and case-insensitive lookups are an equal_range on `folded`.
enum class Target : std::uint8_t { Entry, Recipe, Compare, Index };
struct Key {
  std::string_view key{}, folded{};  // folded: ASCII lowercase of key
  Target target = Target::Entry;
  std::int32_t index = -1;
};

// The search index (PLAN §8.3): for every word, the documents that contain it
// and where. Phrase terms are whole tags (their words joined by one space);
// they only match a query that equals the tag.
enum class Field : std::uint8_t {
  Id,      // a word of an id, alias or compare subject
  Tag,     // a word of a tag
  Phrase,  // a whole tag
  Text,    // a word of a summary or title
  Name,    // a word of an index name that has no card
};
struct Posting {
  Target target = Target::Entry;
  Field field = Field::Id;
  std::int32_t index = -1;
};
struct Term {
  std::string_view term{};
  std::span<const Posting> postings{};
};

namespace data {
// Defined in the generated data.cpp. Every table is sorted by its id.
std::span<const Entry> entries() noexcept;
std::span<const Recipe> recipes() noexcept;
std::span<const Compare> compares() noexcept;
std::span<const Header> headers() noexcept;
std::span<const IndexName> index_names() noexcept;
std::span<const Key> keys() noexcept;
std::span<const Term> terms() noexcept;  // sorted by term
// CHANGELOG.md section of this version, without its heading.
std::string_view changelog() noexcept;
}  // namespace data

}  // namespace cxxman
